mapper.select:
SELECT
DATE_FORMAT(create_time, '%Y-%m') DATE_FORMAT(create_time, '%Y-%u') DATE_FORMAT(create_time, '%Y-%m-%d') AS dimension, COUNT(*) AS orderCount, SUM(pay_amount) AS salesAmount, AVG(pay_amount) AS avgOrderValue FROM oms_order WHERE status IN (2, 3, 4, 5, 6)
AND create_time >= #{param.startTime}
AND create_time <= #{param.endTime}
AND shop_id = #{param.shopId}
GROUP BY dimension ORDER BY dimension

SELECT oi.product_id AS productId, oi.product_name AS productName, SUM(oi.product_quantity) AS saleCount, SUM(oi.product_price * oi.product_quantity) AS salesAmount, IFNULL( (SELECT COUNT(*) FROM oms_order_return_apply ra INNER JOIN oms_order_item oi2 ON ra.order_id = oi2.order_id WHERE oi2.product_id = oi.product_id AND ra.status = 1) * 1.0 / NULLIF(SUM(oi.product_quantity), 0), 0 ) AS refundRate FROM oms_order_item oi INNER JOIN oms_order o ON oi.order_id = o.id WHERE o.status IN (2, 3, 4, 5, 6)
AND o.create_time >= #{param.startTime}
AND o.create_time <= #{param.endTime}
AND o.shop_id = #{param.shopId}
AND oi.product_id = #{param.productId}
GROUP BY oi.product_id, oi.product_name ORDER BY salesAmount DESC

SELECT
    p.product_category_id AS categoryId,
    pc.name AS categoryName,
    COUNT(DISTINCT o.id) AS orderCount,
    SUM(oi.product_price * oi.product_quantity) AS salesAmount,
    ROUND(
        SUM(oi.product_price * oi.product_quantity) * 100.0
        / NULLIF((SELECT SUM(oi3.product_price * oi3.product_quantity)
                  FROM oms_order_item oi3
                  INNER JOIN oms_order o3 ON oi3.order_id = o3.id
                  WHERE o3.status IN (2, 3, 4, 5, 6)

                      AND o3.create_time >= #{param.startTime}


                      AND o3.create_time <= #{param.endTime}


                      AND o3.shop_id = #{param.shopId}
                  ), 0),
        2
    ) AS ratio
FROM oms_order_item oi
INNER JOIN oms_order o ON oi.order_id = o.id
INNER JOIN pms_product p ON oi.product_id = p.id
INNER JOIN pms_product_category pc ON p.product_category_id = pc.id
WHERE o.status IN (2, 3, 4, 5, 6)

    AND o.create_time >= #{param.startTime}


    AND o.create_time <= #{param.endTime}


    AND o.shop_id = #{param.shopId}


    AND p.product_category_id = #{param.categoryId}

GROUP BY p.product_category_id, pc.name
ORDER BY salesAmount DESC
